const specs=[["src-23","REVIEW",1,0,"FM alıcının görevinde taşıyıcı frekansla gönderilmiş bilgi nasıl geri kazanılır?",["Uygun RF kanalı seçilip FM demodülasyonu uygulanarak","Antenin fiziksel boyunu tek başına ses sinyaline çevirerek","Hiç devre olmadan otomatik 100 W ses üreterek"],"Bu kart FM alıcı bloğunu tanıtır; RF kanal seçimi, demodülasyon, duyarlılık ve ses çıkışı ölçülmemiştir.",["FM alıcının önce istasyonu seçip sonra frekans değişiminden bilgi çıkardığını düşün.","Karttaki tek alıcı referansını çalışır RF devresi veya ölçülmüş yayın gibi yorumlama."]],["src-27","REVIEW",4,0,"Bir eko etkisinde asıl işarete hangi işaret eklenir?",["Gecikmiş ve genellikle daha düşük seviyeli kopyası","Anında eşit fazlı bir şebeke beslemesi","Sadece ölçü aletinin etiket bilgisi"],"Eko için gecikme ve karıştırma yolu gerekir. Buradaki parça referansları gecikme hattı veya gerçek ses işleme zinciri değildir.",["Kısa bir sesin biraz sonra daha zayıf tekrar geldiğini hayal et.","Gecikme ile yalnız RC elemanı görmenin aynı şey olmadığını ayırt et."]],["outline-031","REVIEW",3,0,"LC osilatörün sürdürülen salınımı için rezonans tankına ek olarak ne gerekir?",["Uygun faz ve kazançta aktif geri besleme","Yalnız bobinle kondansatörü yan yana koymak","Herhangi bir röle kontağını bağlamadan açmak"],"L ve C rezonansla frekans seçimini etkiler; bu kablosuz referans kartı üretilen dalga/frekans kanıtı değildir.",["Bobin ve kondansatörün enerji alışverişini kavramsal olarak düşün.","Gerçek osilatör için aktif geri besleme koşulunun da gerektiğini belirt."]],["outline-032","REVIEW",3,0,"Kuvars kristal osilatör neden uygun sürücü ve yük kapasitansı ister?",["Rezonansın hedef frekansta güvenilir biçimde uyarılıp sürdürülebilmesi için","Kristal kendi başına elektrik enerjisi ürettiği için","Kondansatörün renginin frekansı seçmesi için"],"Kristal rezonatör frekans seçimine yardımcı olur; bu kartta bağlı sürücü ve ölçülmüş çıkış yoktur.",["Kristali sürücü, yük ve çıkış ölçümünden ayrı tanı.","Görünen HC49 kristali otomatik 4 MHz dalga kanıtı sanma."]],["outline-033","REVIEW",3,0,"RC osilatörde yalnız bir R ve C göstermek niçin yeterli değildir?",["Faz ve kazanç koşulunu sağlayan bağlı aktif çevrim de gerekli olduğu için","Her RC devresi otomatik ses osilatörü olduğu için","Gerilim kaynağının rengi dalga biçimini belirlediği için"],"RC zamanlama ağı frekansı etkiler; bağlantısız elemanlar tek başına salınım oluşturmaz.",["RC zamanlamayla aktif geri besleme koşulunu ayır.","Bu kartı çalışan osilatör deneyi değil kavramsal örnek olarak kullan."]],["outline-034","REVIEW",4,0,"Hangi multivibratör dış tetik olmadan periyodik olarak durum değiştirir?",["Kararsız (astable) multivibratör","İki kararlı durumu olan bistable bellek","Yalnız tetikleyince tek darbe üreten monostable"],"Kararsız model sürekli durum değiştirir; tek kararlı bir darbe sonrası geri döner, çift kararlı ise komutla durum saklar. Bu kartta kablolu dinamik yoktur.",["Tek, çift ve kararsız durum modellerini yan yana düşün.","Gerçek BD139 dalga biçimi bu referans kartında ölçülmez."]],["outline-035","REVIEW",4,0,"Colpitts osilatörde LC geri beslemesi hangi bölümle paylaşılır?",["İki kondansatörlü kapasitif bölücüyle","İki bobinli endüktif tap üzerinden","Bağlantısız bir ölçü aletiyle"],"Bu kart C1/C2 ve bobini ayrı malzemeler olarak gösterir; bağlı Colpitts osilatörü değildir.",["Colpitts için kapasitif bölücüyü ayırt et.","Bu referanstan gerçek çıkış frekansı veya salınım iddiası çıkarma."]],["outline-036","REVIEW",4,0,"Hartley osilatörün Colpitts'ten farklı geri besleme biçimi nedir?",["Tapli/kuplajlı endüktans üzerinden geri besleme","Yalnız iki kapasitörlü gerilim bölücüsü","Çıkışa bağlı bir dijital veri kablosu"],"İki ayrı bobin simgesi gerçek manyetik kuplaj veya tapli bobin modeli oluşturmaz; frekans ve çıkış doğrulanmamıştır.",["Hartley'de sarım oranının geri besleme rolünü tanı.","Kablolanmamış bobinleri çalışır osilatör olarak gösterme."]],["outline-037","REVIEW",3,0,"Kristal osilatör deneyinde gerçek frekansı doğrulamak için hangisi gerekir?",["Uygun kristal sürme/yük devresi ve çıkış ölçümü","Kristalin yalnız kütüphanede bulunması","Kristalin üstündeki sayının tek başına ölçüm sayılması"],"Bu referansta kristal, transistör ve kondansatör bağlantısızdır; ölçülmüş frekans yoktur.",["Sürücü, kristal ve yük kapasitansı arasındaki işlev farkını öğren.","Görüntüdeki parçalardan ölçüm yapılmış sonucu çıkarma."]],["outline-038","REVIEW",7,0,"Üç kademeli RC faz kaymalı osilatörde RC ağı ne sağlar?",["Geri besleme için gereken faz kaymasının bir bölümünü","Transistörün beslemesinin fiziksel testini","Her frekansta eşit büyüklükte doğrudan DC çıkışı"],"Üç RC kademe ve yeterli aktif kazanç birlikte değerlendirilmeli; mevcut kartta bu bağlantılar yoktur.",["Üç RC kolunun faz etkisini ve aktif kazanç gereğini ayır.","Kablolanmamış LM358 görselini çalışan osilatör sayma."]],["outline-039","REVIEW",5,0,"Wien köprü osilatörde RC köprüsünün temel görevi nedir?",["Frekans seçen geri besleme yolu oluşturmak","Kazanç kontrolü olmadan her zaman kararlı genlik vermek","Bir lambayı doğrudan şebekeye bağlamak"],"Yaklaşık frekans seçimi RC oranlarına bağlıdır; aktif kazanç ve genlik denetimi ayrıca gerekir. Bu kartta osilasyon ölçülmemiştir.",["Wien seri/paralel RC yollarını ve aktif yükselteç ihtiyacını ayır.","Bu kartta gerçek genlik kararlılığı kanıtı olmadığını belirt."]],["outline-040","SOURCE_WIRED_MONOSTABLE_NATIVE_IDEAL",13,21,"İki BD139'lu sanal tek kararlı devrede kısa tetik sonrası ne gözlenir?",["İdeal RC süresi boyunca geçici darbe, ardından tek kararlı duruma dönüş","İki ayrı SET/RESET komutuyla süresiz bellek","Tetik yokken sonsuza dek periyodik osilasyon"],"Bağlı sanal model yaklaşık 693 ms ideal RC darbe üretir; gerçek fiziksel BD139/SPICE dinamiği kabul edilmedi."],["outline-041","SOURCE_WIRED_BISTABLE_NATIVE_IDEAL",13,20,"İki BD139'lu sanal çift kararlı devrede SET bırakılınca ne olur?",["İdeal bellek RESET komutuna kadar son durumunu korur","Her 693 ms'de kendiliğinden yön değiştirir","Devre yalnız bir RC darbesinin sonunda sıfırlanır"],"Sanal SET/RESET durum belleği iki kararlı durum gösterir; gerçek fiziksel metastabilite ve üretici kabulü yoktur."],["outline-042","SOURCE_WIRED_CROSS_RC_NATIVE_IDEAL",9,14,"İki BD139'lu kararsız sanal multivibratörde Q1 ve Q2 nasıl davranır?",["İdeal çapraz RC gecikmeyle dönüşümlü iletime geçer","Yalnız SET verilince kalıcı aynı durumda kalır","Bağımsız tek darbe üretip tamamen durur"],"Bu özel sanal model yaklaşık 0,721 Hz ideal periyot verir; fiziksel transistör/başlatma toleransı simüle edilmez."],["outline-043","SOURCE_WIRED_NE555_ASTABLE_FREQUENCY_PENDING",8,15,"NE555 astable bağlantısında zamanlama aralığını hangi parçalar belirler?",["RA/RB dirençleri ile zamanlama kondansatörü","Yalnız çıkış LED'inin rengi","Beslemeden bağımsız bir röle kontağı"],"Pin 7 deşarj yolu ve RC şeması mevcuttur; bu bağımsız kartın gerçek native frekans/LED yanıp sönmesi henüz doğrulanmadı."],["outline-044","SOURCE_WIRED_PWM_DUTY_NATIVE_PENDING",11,19,"Sanal NE555 PWM devresindeki iki ters yönlü diyodun amacı nedir?",["Potansiyometrenin şarj ve deşarj yollarını ayırmak","NE555'i şebeke transformatörüne dönüştürmek","Kondansatörü kalıcı olarak devreden çıkarmak"],"Diyotlu RC görev çevrimi şeması kayıtlıdır; gerçek osiloskop dalgası ve native görev çevrimi kabulü hâlâ açık."],["outline-045","REVIEW",4,0,"NE555 tek kararlı kartında çıkış darbesi için ne gereklidir?",["Tetik girişi ve zamanlama RC yolu","SET/RESET komutlarıyla sınırsız kalıcı bellek","Hiç bağlı eleman olmadan kesin 1 Hz salınım"],"Bu kartta giriş tetikleme ve çıkış darbesi kablolanmamıştır. NE555 dinamik kabulü verilmez.",["Tek kararlı çalışma ile sürekli astable osilasyonu karşılaştır.","Buton ve kondansatör simgelerini tamamlanmış deney gibi yorumlama."]],["outline-046","REVIEW",4,0,"NE555 çift kararlı devrede SET ile RESET görevleri nasıl ayrılır?",["SET durumu seçer; RESET başka duruma döndürür","Her ikisi de yalnız frekansı sürekli artırır","Kondansatör kapasitesi tek başına kalıcı belleği doğrular"],"Bu kartta 555 pinleri ve saklanan çıkış kablolanmamıştır; yalnız SET/RESET kavramını anlatır.",["İki butonu yalnız SET ve RESET işlevinin referansı olarak gör.","Çıkış belleği veya gerçek NE555 dalga biçimi doğrulanmış sayılmaz."]]];
